using System.Text.Json.Nodes;
using FrioTrack.Api.Shared.Application;
using Microsoft.AspNetCore.Mvc;

namespace FrioTrack.Api.Interfaces;

public static class Av2Endpoints {
    static string Authorization(HttpContext context) => context.Request.Headers.Authorization.ToString();
    static JsonObject Body(object input,string? id=null) { var body=RelationalWorkspaceService.Object(input);if(id is not null)body["id"]=id;return body; }
    static RouteHandlerBuilder Mutation(RouteHandlerBuilder endpoint,string name,string tag,string summary) => endpoint.WithName(name).WithTags(tag).WithSummary(summary).Produces<MutationResponse>().Produces<ErrorResponse>(400).Produces<ErrorResponse>(401).Produces<ErrorResponse>(403).Produces<ErrorResponse>(404).Produces<ErrorResponse>(409);
    public static void MapAv2Endpoints(this WebApplication app) {
        app.MapGet("/api/health",()=>new{status="ok",service="FrioTrack",version="0.2.0",persistence="postgresql",telemetry="demonstration"}).WithName("GetHealth").WithTags("Health").WithSummary("Check availability and the active persistence mode.");
        app.MapPost("/api/auth/login",(LoginRequest body,RelationalWorkspaceService service)=>service.Login(Body(body))).RequireRateLimiting("auth").WithName("Login").WithTags("Identity").WithSummary("Sign in with email and password; the server selects the account role.").Produces(200).Produces<ErrorResponse>(401).Produces<ErrorResponse>(429);
        app.MapPost("/api/auth/register",(RegistrationRequest body,RelationalWorkspaceService service)=>service.Register(Body(body))).RequireRateLimiting("auth").WithName("RegisterCargoClient").WithTags("Identity").WithSummary("Register a cargo client in the configured public organization; coordinator registration is forbidden.").Produces(200).Produces<ErrorResponse>(400).Produces<ErrorResponse>(403).Produces<ErrorResponse>(409);
        app.MapPost("/api/auth/logout",async(HttpContext context,RelationalWorkspaceService service)=>{await service.Logout(Authorization(context));return Results.NoContent();}).WithName("Logout").WithTags("Identity").WithSummary("Revoke the current opaque session token.").Produces(204).Produces<ErrorResponse>(401);
        app.MapGet("/api/workspace",(HttpContext context,RelationalWorkspaceService service)=>service.Workspace(Authorization(context))).WithName("GetWorkspace").WithTags("Workspace").WithSummary("Get the authorized SPA projection; a cargo client receives only its assigned shipments.").Produces<WorkspaceResponse>().Produces<ErrorResponse>(401);
        foreach(var collection in new[]{"shipments","vehicles","drivers","sensors","alerts","notifications","profiles"}) {
            var key=collection;
            app.MapGet("/api/"+key,async(HttpContext context,RelationalWorkspaceService service)=> {var workspace=await service.Workspace(Authorization(context));return Results.Json(workspace["state"]![key]);}).WithName("List"+char.ToUpperInvariant(key[0])+key[1..]).WithTags(char.ToUpperInvariant(key[0])+key[1..]).WithSummary("List authorized "+key+" in the current organization.").Produces(200).Produces<ErrorResponse>(401);
            if(key is "profiles" or "notifications")continue;
            app.MapGet("/api/"+key+"/{id}",async(string id,HttpContext context,RelationalWorkspaceService service)=> {var workspace=await service.Workspace(Authorization(context));var item=workspace["state"]![key]!.AsArray().FirstOrDefault(x=>x?["id"]?.ToString()==id);return item is null ? Results.NotFound(new ErrorResponse("notFound","The requested record was not found.")) : Results.Json(item);}).WithName("Get"+char.ToUpperInvariant(key[0])+key[1..]).WithTags(char.ToUpperInvariant(key[0])+key[1..]).WithSummary("Get one authorized record; inaccessible records return 404.").Produces(200).Produces<ErrorResponse>(401).Produces<ErrorResponse>(404);
        }
        Mutation(app.MapPost("/api/shipments",(ShipmentRequest input,HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"createShipment",Body(input))),"ScheduleShipment","Shipments","Schedule a shipment and reserve both resources in one transaction.");
        Mutation(app.MapPut("/api/shipments/{id}",(string id,ShipmentRequest input,HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"updateShipment",Body(input,id))),"UpdateShipment","Shipments","Update a scheduled shipment using its current version and revalidate resource reservations.");
        Mutation(app.MapDelete("/api/shipments/{id}",(string id,[FromQuery]long version,HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"deleteShipment",new JsonObject{["id"]=id,["version"]=version})),"DeleteScheduledShipment","Shipments","Delete only a scheduled shipment with no readings. Pass the expected version as a query parameter.");
        Mutation(app.MapPost("/api/shipments/{id}/transitions",(string id,TransitionRequest input,HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"transition",Body(input,id))),"TransitionShipment","Shipments","Start transit, deliver or cancel before transit. Cancellation requires a note.");
        Mutation(app.MapPost("/api/shipments/{id}/readings",(string id,ReadingRequest input,HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"addReading",Body(input,id))),"RecordDemonstrationReading","Monitoring","Record an authorized demonstration reading; this is not an authenticated physical-sensor ingestion endpoint.");
        Mutation(app.MapPost("/api/shipments/{id}/signal-evaluations",(string id,HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"checkSignal",new JsonObject{["id"]=id})),"EvaluateSignal","Monitoring","Evaluate communication silence on demand; no background IoT ingestion is implied.");
        Mutation(app.MapPost("/api/shipments/{id}/incidents",(string id,IncidentRequest input,HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"recordIncident",Body(input,id))),"RecordIncident","Shipments","Record a dated operational incident and audit the actor.");
        Mutation(app.MapPost("/api/alerts/{id}/corrective-actions",(string id,CorrectiveActionRequest input,HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"recordCorrectiveAction",Body(input,id))),"AcknowledgeAlert","Alerts","Acknowledge an alert with a corrective action; this does not resolve the excursion.");
        Mutation(app.MapPost("/api/vehicles",(VehicleRequest input,HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"saveVehicle",Body(input))),"CreateVehicle","Fleet","Create a vehicle; a sensor may be assigned separately.");
        Mutation(app.MapPut("/api/vehicles/{id}",(string id,VehicleRequest input,HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"saveVehicle",Body(input,id))),"UpdateVehicle","Fleet","Update a vehicle only when it has no active reservation.");
        Mutation(app.MapPost("/api/drivers",(DriverRequest input,HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"saveDriver",Body(input))),"CreateDriver","Fleet","Create an independently managed driver.");
        Mutation(app.MapPut("/api/drivers/{id}",(string id,DriverRequest input,HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"saveDriver",Body(input,id))),"UpdateDriver","Fleet","Update a driver only when it has no active reservation.");
        Mutation(app.MapPost("/api/sensors",(SensorRequest input,HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"saveSensor",Body(input))),"CreateSensor","Fleet","Create an independent sensor root, optionally assigned to one vehicle.");
        Mutation(app.MapPut("/api/sensors/{id}",(string id,SensorRequest input,HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"saveSensor",Body(input,id))),"UpdateSensor","Fleet","Assign, unassign or update a sensor without composing it inside Vehicle.");
        app.MapGet("/api/profiles/me",async(HttpContext context,RelationalWorkspaceService service)=>{var workspace=await service.Workspace(Authorization(context));return Results.Json(workspace["profile"]);}).WithName("GetMyProfile").WithTags("Identity").Produces<ProfileResponse>().Produces<ErrorResponse>(401);
        Mutation(app.MapPut("/api/profiles/me",(ProfileRequest input,HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"updateProfile",Body(input))),"UpdateMyProfile","Identity","Update only the signed-in profile; role and organization ownership cannot be escalated.");
        Mutation(app.MapPost("/api/notifications/read",(HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"readNotifications",new JsonObject())),"ReadMyNotifications","Notifications","Mark only the current recipient's notifications as read.");
        Mutation(app.MapPost("/api/shipments/{id}/reports",(string id,HttpContext context,RelationalWorkspaceService service)=>service.Command(Authorization(context),"generateReport",new JsonObject{["id"]=id})),"GenerateThermalReport","Reports","Explicitly generate a snapshot for a delivered shipment; delivery does not generate it automatically.");
        app.MapGet("/api/reports/{id}",(string id,HttpContext context,RelationalWorkspaceService service)=>service.ReadReport(Authorization(context),id)).WithName("GetThermalReport").WithTags("Reports").WithSummary("Retrieve an authorized immutable thermal report snapshot with demonstration provenance.").Produces(200).Produces<ErrorResponse>(401).Produces<ErrorResponse>(404);
    }
}
